//! CPU render backend/reference; opt-in professional reference cases require external independent
//! oracles.
//!
//! Implements the pigment-owned `RenderBackend` port (`hsk_studio_pigment::render_plan`) for
//! `Renderer`. The plan IR, `StudioBlendMode`, the receipt and the ONLY blend arithmetic
//! (`hsk_studio_pigment::blend_math`) live in pigment (CX-CAP-001); this crate adds bounded
//! chunked execution, groups, masks, vector coverage, budgets and cancellation.
#![forbid(unsafe_code)]
mod coverage;
pub mod plan_sink;
mod px;
pub mod report;
pub mod vector;

pub use plan_sink::{
    DEFAULT_CHUNK_SIDE, DISPLAY_CLIP_EXACTNESS, DISPLAY_CLIP_OPERATOR, DisplayTransform, MAX_CHUNK_SIDE, MAX_EFFECT_WINDOW_WORK, MAX_PATH_ELEMENTS, MAX_THREADS,
    RENDERER_NAME, RENDERER_VERSION, RenderError, Renderer, SourceFault, blend_supported,
};
pub use report::{outcome_of, report};
pub use vector::{VectorFill, VectorSource};

pub const DESCRIPTOR: &str = r#"{"module":"STUDIO-MODULE-RENDER_CPU","version":1,"renderer":"hsk-studio-render-cpu/0.1","operation":"execute_render_plan_to_tile_sink","api":"impl RenderBackend<V: VectorSource> for Renderer (pigment render_plan port); Renderer::execute_detailed keeps the internal error; report(result, correlation, revision, cancel, observe, sink) emits one terminal Observe frame","command":"render-cpu-consumer --descriptor | --selftest","plan":"hsk_studio_pigment::render_plan::RenderPlan (tile, solid, vector, group{isolated, layers bottom-first}, layer{mode, opacity, fill_opacity, mask (coverage plane or clip_to_base)}); admit() runs first","blend":{"owner":"hsk_studio_pigment::blend_math (single owner); render-cpu keeps no blend arithmetic","numerics":"binary32 per pigment; inputs outside [0,1] are refused, never clamped in, unless the plan output stage is Extended (display_transform)","supported":"every layer-applicable mode with a recovered function; refused: pass_through as a blend, behind/clear (tool-only), average/negation/reflect/glow/erase (no function)","parity":"exactness classes come from pigment facts; Adobe output parity NOT_PROVEN"},"operators":{"exact":["tile","solid","group_isolated","group_pass_through","mask coverage_u8/coverage_u16le"],"approximate":["vector (supersampled coverage)","fill_opacity (folded into opacity as a product)","clip_to_base (pigment run semantics, Photoshop rule UNVERIFIED)"],"unsupported":["group_pass_through_opacity","group_pass_through_fill_opacity","group_non_isolated_blended","mask density other than 1 on the v1 execute path (execute_extended admits it)","knockout shallow/deep","Blend-If on a clip base or a clipped layer (blend_if_clip_base, blend_if_clipped_layer: refused by pigment admission)","mask on a pass-through layer (mask_on_pass_through: refused by pigment admission for every backend)","clip base that is a pass-through group (refused by plan validation: plan_clip_base_pass_through)","premultiplied alpha (alpha_premultiplied: declared Unsupported through extension_exactness, so pigment admission refuses it)","samples outside [0,1] in a unit-range plan"]},"display_transform":"plan output stage (lanes SMB-RENDER-SCENE-DISPLAY, SMB-PIGMENT-EXTENDED-RANGE): pigment PlanExtensions.output = OutputStage{sample_range, display}; ExtOperator::ExtendedRange and DisplayClip declared with pigment classes (approximate, exact); Extended admits any finite tile, Solid and vector fill colour (alpha [0,1]) and composites every layer with pigment blend_math::composite_over_extended (render-cpu keeps no copy), a non-finite result is the typed sample_range_outside_unit; Clip clamps the chunk colour into [0,1] before the sink (stage 6a); modes undefined above 1 and envelope layer entries are refused by pigment admission (sample_range_extended_mode, sample_range_extended_combination) before any sink call; the default stage takes the unchanged unit path, byte for byte (tests cpu_extended_range unit_default_is_byte_identical_and_extended_stage_matches_pigment_for_every_chunking, hostile_values_in_an_extended_plan_are_typed); Renderer::with_display_transform is a deprecated alias: a plan without its own stage runs with OutputStage{Extended, Some(transform)} and the receipt digest is that envelope's (tests cpu_scene_display clip_matches_the_pigment_composite_of_clipped_sources_for_every_chunking_and_thread_count, undeclared_keeps_the_refusal_and_declared_clip_refusals_are_typed, hostile_samples_under_a_declared_clip_stay_typed_or_clip)","clip_to_base":"supports_clip_to_base = true; run [base, c1..cn] (base = nearest earlier unclipped layer of the group) is evaluated per chunk into one scratch buffer G: G = base content with the base's own mask (no opacity/fill/mode); each ci blended onto G with its own mode/opacity/fill and source alpha * base alpha, then G alpha held at the base alpha; G composited onto the backdrop with the base's mode/opacity/fill; clipped content never extends beyond the base (group extent ignores clipped layers); one extra scratch buffer level per run","extensions":"RenderBackend::execute_extended (Renderer::execute_extended_detailed): admit_extended first, then the same chunked loop; adjustment layer = pigment adjust_math::composite_adjustment on the group running buffer (alpha unchanged; inside a clip run it adjusts the run buffer G only); Blend-If = coverage_math::blend_if_weight multiplies the source alpha (this layer is the source, for an adjustment layer its content f(backdrop); underlying is the running backdrop); mask density/invert = coverage_math::mask_coverage; mask feather = separable coverage_math::feather_kernel blur of the coverage plane per chunk, read with a feather_support margin and clamped at the mask plane border, applied before density; knockout shallow/deep are Unsupported; Blend-If on a clip base or a clipped layer is refused by pigment admission as blend_if_clip_base | blend_if_clipped_layer before any sink call and render-cpu applies none (test cpu_extended blend_if_on_clip_roles_is_refused_before_any_sink_call); formulas and intrinsic classes (Approximate) are pigment's, render-cpu keeps no copy; Photoshop parity NOT_PROVEN; resident envelope tables and the per-worker feather scratch are charged to max_working_bytes before any sink call (test mask_feather_hand_values_budget_and_aggregate); an empty envelope without a density mask takes the v1 path with identical bytes (test refusals_stay_typed_and_the_v1_path_is_unchanged)","effects":"layer effects waves 1 and 2 (drop shadow, colour overlay, solid stroke; inner shadow, outer glow, inner glow with colour fill, Softer technique, full range and no jitter; ExtOperator::Effect, Approximate, Photoshop parity NOT_PROVEN D5 12-17; a gradient glow, the Precise technique, a range below 100 % and jitter are refused at pigment admission with the feature key before the first sink call, test cpu_effects_fx2 wave2_exactness_refusals_and_budget): the layer is evaluated per chunk window (content bounds grown by the stack margin stack_support_px and clipped to the chunk; any margin, no 64 px plane limit) with WindowGeometry::uncut and composed over the running backdrop by pigment effect_math::window::render_layer_window over an AlphaSource on a content frame, which owns the matte maths, the composition order and the fade rules; render-cpu keeps no copy; a plan renders bit-identical to pigment's render_layer_reference on reference planes that hold the layer plus its margin, for every chunking and thread count (tests cpu_window parity_with_reference_across_chunkings_and_threads, cpu_effects_fx2 wave2_parity_with_reference_across_chunkings_and_workers, cpu_effects effect_stack_matches_reference_for_every_chunking and the shadow/overlay/stroke hand-value tests), and equal to the uncut windowed oracle for margins the reference cannot hold (tests cpu_window large_margin_renders_and_matches_the_uncut_windowed_oracle and cpu_effects_fx2 wave2_large_margin_matches_the_uncut_windowed_oracle); the dissolve mode uses plan coordinates with seed 0; refused as typed Unsupported before the first sink call: a window whose predicted work (pigment layer_window_cost) is above MAX_EFFECT_WINDOW_WORK (effect_work_limit; test work_limit_and_hostile_geometry_stay_typed), effects together with Blend-If on one layer (effects_with_blend_if: intrinsically Unsupported in pigment, refused by shared admission for every backend), effects inside the content of a layer with effects (effects_nested: this backend declares ExtOperator::EffectsNested Unsupported, so shared admission refuses it; test fx_ops_declarations_and_refusals_equal_pigments); the per-worker frame, the window input arrays and pigment's predicted peak (layer_window_cost of the largest window) are part of the reserved scratch and charged to max_working_bytes before the first sink call (tests cpu_window window_cost_is_charged_and_limit_minus_one_is_refused_before_any_sink_call and cpu_effects effect_refusals_and_scratch_charge_stay_typed)","plan_limits":"Renderer::with_plan_limits(PlanLimits) tightens the plan budgets (nodes, layers, nesting depth) that execute_detailed and execute_extended_detailed hand to pigment admit_with_limits | admit_extended_with_limits, so a plan above a tightened budget is refused as an invalid plan before any source lookup or sink call; a field above PlanLimits::MAXIMUM is invalid_config (never clamped); a renderer without limits uses the maxima as before (tests cpu_plan_limits tightened_plan_limits_refuse_before_any_sink_call, default_plan_limits_are_unchanged); the envelope effect budgets stay fixed constants outside PlanLimits","envelope_reach":"only the envelope entries of groups reachable from the root are admitted as capability (pigment) and prepared (this backend), like the layers prepare visits: an entry on a group no layer reaches renders nothing, asks nothing of the backend and charges nothing to max_working_bytes, while the same entry on a reachable group is refused with the same key (test cpu_envelope_reach unreachable_envelope_entries_are_neither_admitted_nor_prepared)","blur":"envelope LayerExtension.blur (lane SMB-COMPOSITE-NEW-KINDS): ExtOperator::Blur(layer|backdrop) declared with pigment's class (approximate); radius r = the shared Gaussian of pigment blur_math (sigma = r / 2, feather_kernel taps); layer blur: the layer shape content (mask in the alpha) evaluated on the chunk-level frame over the window grown by the support and blurred premultiplied by pigment blur_window, composited with mode and opacity * fill; backdrop blur (isolated group only): the group layers below re-evaluated over the window grown by the support, blurred, and mixed into the running buffer inside the layer shape by pigment backdrop_mix (k = shape alpha * layer opacity) before the layer composites; bytes equal the pigment composition for every chunking and thread count (tests/cpu_blur.rs); frame and predicted blur bytes charged before the first sink call; refused typed before any sink call: blur_work_limit, blur_nested (a blur or effects inside a blurred layer, or layers with effects or a blur below a backdrop blur in its group); Figma/Photoshop parity NOT_PROVEN","filters":"envelope LayerExtension.filters (lane SMB-RENDER-FILTERS): ExtOperator::Filter(gaussian_blur|unsharp_mask|high_pass|median|add_noise) declared with pigment's class (approximate); every stage is one call of pigment filter_math::filter_window (the maths owner; render-cpu keeps no filter formula, noise generator or median); the layer content WITHOUT its mask is stage 0, stage k reads the previous stage window grown by its reach (blur support, median radius) and is transparent beyond its bounds grown by the growth (support or radius; point filters add none); the chain is evaluated per chunk window on the chunk-level frame, then composited by the normal path so the layer mask (feather, invert, density), Blend-If, mode and opacity * fill apply after the filters; with a mask the composite covers the mask plane only; bytes equal pigment filter_window applied stage by stage to the whole layer for every chunking and thread count (tests/cpu_filters.rs every_filter_matches_pigment_for_every_chunking_and_thread_count, filters_apply_before_the_layer_mask); refused typed before any sink call: parameters out of range or more than 16 filters (plan_filter_parameter), filters with a blur, effects, transform or adjustment on one layer (plan_filter_combination), filter_work_limit (predicted work of a stage window above MAX_EFFECT_WINDOW_WORK), filter_nested (a filtered layer inside a layer that uses the chunk-level frame), BudgetExceeded when the frame and pigment's predicted stage bytes do not fit max_working_bytes (tests hostile_radii_and_parameters_are_typed_before_any_sink_call, refusals_budget_and_nesting_are_typed_before_any_sink_call); Photoshop parity NOT_PROVEN","content_aware_fill":"envelope LayerExtension.content_aware_fill (lane SMB-RENDER-CONTENT-AWARE): ExtOperator::ContentAwareFill declared with pigment's class (approximate); before the first chunk the layer content WITHOUT its mask is rendered over the content bounds inside the plan extent and handed with the hole (the hole mask source as a coverage plane: u16 as is, u8 times 257, inverted 65535 - c; a render-cpu reading) and the sampling area (none = auto, rect = rectangular) to pigment content_aware::fill (the single owner; render-cpu keeps no patch search, voting or blend); the layer then reads pigment's output plane and the normal path applies the layer mask, Blend-If, mode and opacity * fill; bytes equal a direct pigment fill of the content composited by composite_over for every chunking and thread count and pigment threads option (test cpu_content_aware fill_matches_pigment_for_every_chunking_and_thread_count); the content plane, its group levels, the hole plane and every stored output plane are charged to max_working_bytes after the chunk scratch and before allocation, pigment gets the rest as RetouchLimits.max_bytes and charges its predicted pyramid before allocating, work bound = pigment's default max_work (test budgets_are_charged_before_any_sink_call); refused typed before any sink call: options, hole or sampling out of range (plan_content_aware_parameter), a fill with filters, a blur, effects, a transform, an adjustment or a clip role (plan_content_aware_combination), a fill whose content holds another fill or a layer with effects, a blur or filters (content_aware_nested), an unresolved hole source, pigment's content_aware_hole_too_large | content_aware_no_source | content_aware_option_unsupported, BudgetExceeded (test parameter_and_combination_refusals_are_typed); cancel is observed before each fill, not inside it; Photoshop parity NOT_PROVEN","transform":"envelope LayerExtension.transform on a tile layer (lane SMB-PIGMENT-TRANSFORM): ExtOperator::Transform(nearest_neighbour|bilinear|bicubic) declared with pigment's class (approximate); prepare builds a transformed-tile node read per pixel by pigment transform_math::PreparedTransform::sample_rgba (binary64, the reference itself), and a linked mask (transform_mask) is read by sample_coverage over its plane (zero outside, no gap check); bytes equal the pigment reference for every chunking and thread count, an identity or integer transform equals the untransformed plan (tests cpu_transform cpu_matches_pigment_reference_for_every_chunking_and_thread_count, identity_and_integer_moves_equal_the_untransformed_plan, linked_mask_moves_with_its_content_and_unlinked_mask_stays); hostile matrices, a non-tile input and transform with effects are refused before any sink call with pigment's PlanError values (test hostile_and_undefined_transforms_are_refused_before_any_sink_call)","formats":{"colour":"rgb_f32le","alpha":"f32le straight, separate plane","chunk":"tightly packed row-major, sink receives rect + both planes","parallel":"Renderer::with_threads(chunk, n): scoped workers, bytes and sink order identical to n=1, reorder window 2n chunks, charge = chunk_px*(n*(32+16*depth)+32n) for n>1"},"limits":{"effect_window_work":1000000000,"path_elements":65536,"chunk_side_max":4096,"threads_max":64,"default_chunk_side":64,"scratch_bytes_per_chunk_pixel":32,"scratch_bytes_per_isolated_group_depth_pixel":16,"aa_samples_per_axis":"1..16","case_seconds":30},"vector":"payload VectorFill = nib OwnedPath (plan-pixel coordinates, NonZero|EvenOdd, built from anchors with OwnedPath::from_anchors) + rgba; open subpaths fill as closed; coverage = exact winding of the true curve at n*n pixel-centre samples","colour_management":"none: plan colour tag (profile hash + blend space) must equal every source tag, never converted (STU-COL-163)","failure":"cancel/deadline between chunks; stale revision, invalid plan, unsupported operator, unresolved or mismatching source (hash, stride, declared size/format/tag, mask gap) refuse before the first sink call; sink error aborts; a panic in a worker or the sink is the typed unavailable worker_panic|sink_panic on every thread count, never a hang; scratch released on every exit; receipt only after the last chunk","privacy":"no pixel, profile or path bytes in telemetry","pending":["blend_math owns remaining modes; render-cpu follows its exactness facts","strokes as vector paint, gradients, patterns, layer effects beyond waves 1 and 2 (satin, gradient/pattern overlay, bevel, gradient glows), clipped layer with its own mask (pigment pending)","16/32-bit integer paths, SIMD","external-oracle parity vs Adobe: NOT_PROVEN"]}"#;
